
import themeRed from './theme/red.json';
import themePurple from './theme/purple.json';
import themeBlue from './theme/blue.json';
import themeGreen from './theme/green.json';
import themeOrange from './theme/orange.json';
import themeGray from './theme/gray.json';
import themeDarkgray from './theme/darkGray.json';
import themeBlack from './theme/black.json';

export class Asset {
    // tslint:disable-next-line:no-any
    themeRed: any; themePurple: any; themeBlue: any; themeGreen: any; themeOrange: any; themeGray: any; themeDarkgray: any; themeBlack: any;
    constructor() {
        this.ImportAssets();
    }
    async ImportAssets() {
        this.themeRed = themeRed;
        this.themePurple = themePurple;
        this.themeBlue = themeBlue;
        this.themeGreen = themeGreen;
        this.themeOrange = themeOrange;
        this.themeGray = themeGray;
        this.themeDarkgray = themeDarkgray;
        this.themeBlack = themeBlack;
    }
}